(async()=>{const out={};out.families=['A','A B','"A B"','serif','','A,B','123'].map(x=>{const f=new FontFace(x,'local(Test)');f.loaded.catch(()=>{});return[x,f.family,f.status]});out.sources=[];for(const s of ['','bad','local(Test)','url(data:font/woff;base64,AA==)']){const f=new FontFace('X',s);f.loaded.catch(()=>{});out.sources.push([s,f.status,f.status==='error'?await f.loaded.catch(e=>e.name):null])}const bad=new FontFace('X','local(Test)',{weight:'bad'});bad.loaded.catch(()=>{});out.invalid=[bad.status,bad.weight,await bad.loaded.catch(e=>e.name)];out.brand=await FontFace.prototype.load.call({}).catch(e=>e.name);return out})()
